document.onkeydown=e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName)||$('#modal').open)return;if(e.code==='Space'){e.preventDefault();space=true;canvas.style.cursor='grab'}if(e.key==='Escape'){if(['element','grip','roofGrip'].includes(drag?.kind))model=drag.original;drag=null;points=[];editing=null;tool='select';toolState();render()}if(e.key==='Enter')finish();if(e.key==='Delete'||e.key==='Backspace')edit('delete');if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();e.shiftKey?redo():undo();return}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();save();return}if(e.ctrlKey||e.metaKey)return;if(e.key.toLowerCase()==='s')$('#snap-btn').click();else{let t=toolGroups.flatMap(([, ...ts])=>ts).find(t=>t[2].toLowerCase()===e.key.toLowerCase());if(t)chooseTool(t[0])}};document.onkeyup=e=>{if(e.code==='Space'){space=false;canvas.style.cursor=tool==='select'?'default':'crosshair'}};
function openModal(title,body){$('#modal-title').textContent=title;$('#modal-body').innerHTML=body;icons($('#modal'));$('#modal').showModal()}$('#modal-close').onclick=()=>$('#modal').close();$('#help').onclick=()=>openModal('A workspace built around the model',`<div class="modal-copy">Draft in plan, inspect in 3D, and edit the same building objects in every view.</div><div class="help-list">V — Select &nbsp; W — Wall &nbsp; N — Window &nbsp; D — Door<br>Click twice to draw; double-click to finish polygons.<br>Drag selected elements to move. Shift-click adds selection.<br>Scroll to zoom. Space + drag to pan.<br>In 3D, drag to orbit; Shift + drag to pan.<br>Ctrl Z — Undo &nbsp; Ctrl Shift Z — Redo<br>Save downloads a portable JSON project.</div><div class="modal-copy" style="margin-top:15px">Wall milestone: automatic L/T/X cleanup, connected grips, reference-line controls, composites and timber framing layouts. Frames regenerate from walls and openings. Curved / slanted / tapered walls, profile sections, general CAD fillets, IFC, DWG and sheets remain future stages.</div>`);
function storyDialog(){const st=model.stories.find(s=>s.id===activeStory);openModal('Story settings',`<div class="modal-copy">Walls linked to this story follow its height. Hosted openings stay within their walls. Upper levels move with the new height.</div><label class="modal-field">${esc(st.name)} height <input id="story-height" type="number" value="${st.height}" step="100"></label><div class="modal-actions"><button id="story-apply" class="primary">Update story</button></div>`);$('#story-apply').onclick=()=>{try{setStoryHeight(st.id,Number($('#story-height').value));$('#modal').close()}catch(e){toast(e.message)}}}$('#story-btn').onclick=storyDialog;$('#add-story').onclick=()=>{const last=model.stories.at(-1);commit(()=>model.stories.push({id:'s'+Date.now(),name:'New story',elevation:last.elevation+last.height,height:3048}));toast('New story added to navigator')};
function download(filename,text,mime='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:mime}));a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}function save(){download('courtyard-house.bim.json',JSON.stringify(model,null,2));dirty=false;$('#save-state').textContent='Project saved';toast('Project downloaded as BIM JSON')}$('#save').onclick=save;
function generateOBJ(){let out=['# Atelier BIM world coordinates in meters'],n=1;function mesh(id,ps,z0,z1){out.push('o '+id);const vs=[...ps.map(p=>({...p,z:z0})),...ps.map(p=>({...p,z:z1}))];vs.forEach(p=>out.push(`v ${p.x/1000} ${p.z/1000} ${-p.y/1000}`));const k=ps.length;out.push('f '+ps.map((_,i)=>n+k+i).join(' '));out.push('f '+ps.map((_,i)=>n+k-1-i).join(' '));for(let i=0;i<k;i++){let j=(i+1)%k;out.push(`f ${n+i} ${n+j} ${n+k+j} ${n+k+i}`)}n+=k*2}
for(const face of wallSurfaces(joinedWallCells(model.elements.filter(e=>e.type==='wall')))){out.push('o '+face.id);face.points.forEach(p=>out.push(`v ${p.x/1000} ${p.z/1000} ${-p.y/1000}`));out.push('f '+face.points.map((_,i)=>n+i).join(' '));n+=face.points.length}for(const o of model.elements.filter(e=>e.host)){const w=hostOf(o),len=distance(w.a,w.b),z=wallBase(w);mesh(o.id,openingSolidPolygon(w,o),z+o.sill,z+o.sill+o.height)}for(const e of model.elements){let z=storyOf(e).elevation;if(e.type==='wall'){continue;}else if(e.type==='slab')mesh(e.id,e.points,z-e.thickness,z);else if(e.type==='beam')mesh(e.id,wallPoly(e),z+heightOf(e)-e.thickness,z+heightOf(e));else if(e.type==='column')mesh(e.id,wallPoly(e,{x:e.a.x-e.thickness/2,y:e.a.y},{x:e.a.x+e.thickness/2,y:e.a.y}),z,z+heightOf(e));else if(e.type==='roof'){for(const face of roofGeometry(e).faces){out.push('o '+e.id);face.forEach(p=>out.push(`v ${p.x/1000} ${p.z/1000} ${-p.y/1000}`));out.push('f '+face.map((_,i)=>n+i).join(' '));n+=face.length}}}return out.join('\n')}
function csv(){return 'ID,Type,Story,Material,Length mm,Height mm\n'+model.elements.map(e=>[e.id,e.type,storyOf(e).name,e.material,e.a&&e.b?Math.round(distance(e.a,e.b)):'',e.height?heightOf(e):''].map(x=>'"'+String(x||'').replace(/"/g,'""')+'"').join(',')).join('\n')}
