function validateProject(m){if(!m||m.version!==1||!Array.isArray(m.stories)||!m.stories.length||!Array.isArray(m.elements)||m.elements.length>10000)throw Error('This is not a supported Atelier BIM project.');if(m.views?.sectionA&&(!Number.isFinite(m.views.sectionA.position)||Math.abs(m.views.sectionA.position)>1000000||m.views.sectionA.axis!=='y'))throw Error('Invalid section view.');let ids=new Set();for(const s of m.stories){if(typeof s.id!=='string'||ids.has(s.id)||typeof s.name!=='string'||!Number.isFinite(s.height)||s.height<=0||!Number.isFinite(s.elevation))throw Error('Invalid story data.');ids.add(s.id)}ids=new Set();const types=toolGroups.flatMap(([, ...ts])=>ts.map(t=>t[0]));for(const e of m.elements){if(!types.includes(e.type)||typeof e.id!=='string'||ids.has(e.id)||!m.stories.some(s=>s.id===e.story))throw Error('Invalid element data.');ids.add(e.id);for(const p of [e.a,e.b,...(e.points||[])].filter(Boolean)){if(!Number.isFinite(p.x)||!Number.isFinite(p.y))throw Error('Invalid geometry.')}if(['wall','beam','line','dimension'].includes(e.type)&&(!e.a||!e.b||distance(e.a,e.b)<1))throw Error('Invalid segment.');if(['wall','beam','column','slab'].includes(e.type)&&(!Number.isFinite(e.thickness)||e.thickness<=0))throw Error('Invalid thickness.');if(['slab','roof','rectangle','zone'].includes(e.type)&&(!Array.isArray(e.points)||e.points.length<3))throw Error('Invalid boundary.');if(['circle','arc'].includes(e.type)&&(!e.a||!Number.isFinite(e.radius)||e.radius<=0))throw Error('Invalid curve.');if(e.type==='dimension'&&(e.offset!==undefined&&!Number.isFinite(e.offset)||e.refs&&(!Array.isArray(e.refs)||e.refs.length!==2||e.refs.some(r=>r&&(typeof r.elementId!=='string'||!['a','b'].includes(r.point))))))throw Error('Invalid dimension reference.');if(e.height!==undefined&&(!Number.isFinite(e.height)||e.height<=0))throw Error('Invalid height.')}m.elements.filter(e=>e.type==='roof').forEach(validateRoof);for(const w of m.elements.filter(e=>e.type==='wall')){validateConstruction(w);if(w.topStory&&!m.stories.some(s=>s.id===w.topStory))throw Error('Invalid top-linked story.');if(w.priority!==undefined&&(!Number.isFinite(w.priority)||w.priority<0||w.priority>1000))throw Error('Invalid join priority.');}if(m.elements.filter(e=>e.type==='wall').reduce((n,w)=>n+distance(w.a,w.b)/construction(w).spacing,0)>100000)throw Error('Project framing exceeds the interactive member limit.');for(const e of m.elements.filter(e=>e.host)){let w=m.elements.find(w=>w.id===e.host);if(!w||w.type!=='wall'||![e.offset,e.width,e.height,e.sill].every(Number.isFinite)||e.width<=0||e.height<=0||e.sill<0||e.offset-e.width/2<0||e.offset+e.width/2>distance(w.a,w.b))throw Error('Invalid hosted opening.');const home=m.stories.find(s=>s.id===w.story),top=m.stories.find(s=>s.id===w.topStory),wh=w.followStory?(top?top.elevation:home.elevation+home.height)+(w.topOffset||0)-home.elevation-(w.baseOffset||0):(w.height||3000);if(e.sill+e.height>wh||e.reveal!==undefined&&(!Number.isFinite(e.reveal)||e.reveal<0||e.reveal>Math.max(0,w.thickness-40))||m.elements.some(o=>o.id!==e.id&&o.host===w.id&&Math.abs(o.offset-e.offset)<(o.width+e.width)/2))throw Error('Invalid opening bounds or overlap.');}return m}
$('#import-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>10000000)throw Error('Project file is too large.');let imported=JSON.parse(await file.text());for(const w of imported.elements||[])if(w.type==='wall'&&!w.reference&&w.layer==='Exterior Walls')w.reference='outside';let m=validateProject(imported);commit(()=>{model=m;activeStory=model.stories[0].id;selected=[]});setView('plan');fit();toast('BIM project opened')}catch(err){toast(err.message)}e.target.value=''};
